// Learning how to do nice looking raymarching
// Heavily borrowed from Inigo Quilez and Shane

#define sEPS 0.001 // Minimum surface distance threshold.
#define FAR 60. // Maximum ray distance threshold.
#define AA 2 // Anti-Aliasing
#define SPEED 0.
#define VOLUMETRIC_STEP_SIZE 0.08
#define MAX_STEPS 128

#define PI 3.1415926535

//#define ATTENUATION
//#define SHADOWS
#define AMBIENT_OCCLUSION
#define PHONG_SHADING
#define ENABLE_OPAQUE
//#define ENABLE_VOLUMETRIC
//#define NORMALS_DEBUG

struct PhongParameters {
    vec3 ambient;
    vec3 diffuse;
    vec3 specular;
    float specularExponent;
};

struct Material {
    vec3 color;
    int textureID;
    PhongParameters phongParameters;
};

struct MapReturn {
    float sdf;
    Material material;
    vec3 texturePosition;
};

struct VolumetricReturn {
	float density;
	vec3 color;
};

Material brass, white, flesh, brick, rustyMetal, silver, missing;

// Produces rotation matrix given theta
mat2 rot(float th){ float cs = cos(th), si = sin(th); return mat2(cs, -si, si, cs); }

float noise(vec3 x ) {
  vec3 p = floor(x);
  vec3 f = fract(x);
  f = f*f*(3.0-2.0*f);

  vec2 uv = (p.xy+vec2(37.0,239.0)*p.z) + f.xy;
  vec2 tex = textureLod(iChannel0,(uv+0.5)/256.0,0.0).yx;

  return mix( tex.x, tex.y, f.z ) * 2.0 - 1.0;
}

float fbm_6(vec3 p) {
  vec3 q = p + iTime * 0.5 * vec3(1.0, -0.2, -1.0);
  float g = noise(q);

  float f = 0.0;
  float scale = 0.5;
  float factor = 2.02;

  for (int i = 0; i < 6; i++) {
      f += scale * noise(q);
      q *= factor;
      factor += 0.21;
      scale *= 0.5;
  }

  return f;
}

float smax( float a, float b, float k )
{
    float h = max(k-abs(a-b),0.0);
    return max(a, b) + h*h*0.25/k;
}

vec3 sphereInversion(vec3 p, vec3 c, float r) {
	vec3 d = p - c;
	float d2 = dot(d, d);
	return c + (r * r / d2) * d;
}

void setMaterials() {
    PhongParameters brassParameters = PhongParameters(vec3(0.329412, 0.223529, 0.027451), vec3(0.780392, 0.568627, 0.113725), vec3(0.992157, 0.941176, 0.807843), 27.8974);
    PhongParameters whiteParameters = PhongParameters(vec3(0.1), vec3(1.), vec3(0.), 1.);
    PhongParameters silverParameters = PhongParameters(vec3(0.19225), vec3(0.50754), vec3(0.508273), 51.2);

    brass = Material(vec3(.7098, .651, .2588), -1, brassParameters);
    flesh = Material(vec3(153./255.,45./255.,27./255.), -1, whiteParameters);
    white = Material(vec3(1.), -1, whiteParameters);
    brick = Material(vec3(1.), 1, whiteParameters);
    rustyMetal = Material(vec3(1.), 2, silverParameters);
    missing = Material(vec3(0., 0., 0.), -1, whiteParameters);
}

MapReturn opUnion(MapReturn a, MapReturn b) {
    if (a.sdf > b.sdf) return b;
    else return a;
}

MapReturn opSmoothUnion(MapReturn a, MapReturn b, float k) {
    MapReturn mp;
    float h = clamp( 0.5 + 0.5*(b.sdf-a.sdf)/k, 0.0, 1.0 );
    mp.sdf = mix( b.sdf, a.sdf, h ) - k*h*(1.0-h);
    // TODO - Material mixing?
    mp.material = a.material;
    mp.texturePosition = a.texturePosition;
    return mp;
}

MapReturn opRound(MapReturn a, float roundingFactor) {
    a.sdf -= roundingFactor;
    return a;
}

MapReturn opOnion(MapReturn a, float thickness) {
    a.sdf = abs(a.sdf) - thickness;
    return a;
}

MapReturn planeSDF(vec3 samplePoint, vec3 normal, float height, Material material) {
    MapReturn mp;
    mp.sdf = abs(dot(samplePoint, normal) - height);
    mp.material = material;
    mp.texturePosition = samplePoint;
    return mp;
}

MapReturn boxSDF(vec3 samplePoint, vec3 bounds, Material material) {
    MapReturn mp;
    vec3 q = abs(samplePoint) - bounds;
    mp.sdf = length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
    mp.material = material;
    mp.texturePosition = samplePoint;
    return mp;
}

MapReturn sphereSDF(vec3 samplePoint, float size, Material material) {
	MapReturn mp;
	mp.sdf = length(samplePoint) - size;
	mp.material = material;
    mp.texturePosition = samplePoint;
	return mp;
}

MapReturn infiniteGridSDF(vec3 position, float s, Material material) {
	MapReturn mp;

	position = position - round(position);

	vec2 q = abs(position.xy) - s;
	float beam1 = length(max(q,0.0)) + min(max(q.x,q.y),0.0);

	q = abs(position.xz) - s;
	float beam2 = length(max(q,0.0)) + min(max(q.x,q.y),0.0);

	q = abs(position.zy) - s;
	float beam3 = length(max(q,0.0)) + min(max(q.x,q.y),0.0);

    mp.sdf = min(beam1, min(beam2, beam3));
    mp.material = material;
    mp.texturePosition = position;
    return mp;
}

MapReturn crossSDF(vec3 position, vec3 r, Material material) {
    MapReturn mp;

    float d1 = length(max(abs(position.xyz)-r, 0.));
    float d2 = length(max(abs(position.zyx)-r, 0.));

    mp.sdf = min(d1, d2);
    mp.material = material;
    mp.texturePosition = position;
    return mp;
}

MapReturn squareRingSDF(vec3 position, float radius, float height, float thickness, Material material) {
    MapReturn mp;
    float sdf = length(position.xz) - radius;
    sdf = abs(sdf)-thickness/2.;
    sdf = smax(sdf, abs(position.y) - height/2., 0.005);
    mp.sdf = sdf;
    mp.material = material;
    mp.texturePosition = position;
    return mp;
}

MapReturn gearToothSDF(vec3 position, vec3 bounds, float rounding, Material material) {
    MapReturn mp;
    vec2 q = abs(position.xz) - bounds.xz;
    mp.sdf = length(max(q,0.0)) + min(max(q.x,q.y),0.0) - rounding;
    mp.sdf = smax(mp.sdf, abs(position.y) - bounds.y/2., 0.005);
    mp.material = material;
    mp.texturePosition = position;
    return mp;
}

MapReturn vStickSDF(vec3 position, float height, float thickness, Material material) {
    MapReturn mp;
    mp.material = material;
    mp.texturePosition = position;
    float d = max(position.y-height, 0.);
    mp.sdf = sqrt(position.x*position.x + position.z*position.z + d*d) - thickness;
    return mp;
}

MapReturn gearSDF(vec3 position, float time, float offset) {
    time += offset*PI*2./24.;
    position.xz = rot(time*sign(position.y)) * position.xz;
    position.y = abs(position.y);
    vec3 gearPosition = position - vec3(0., .5, 0.);
    gearPosition.y += length(gearPosition.xz)*.25;

    float gearSegments = 12.;
    float angle = 6.283185/gearSegments;
    float sector = round(atan(gearPosition.z, gearPosition.x)/angle);

    vec3 gearMap = gearPosition;
    gearMap.xz = rot(sector*angle) * gearMap.xz;
    gearMap -= vec3(0.17, 0., 0.);

    MapReturn roundedBox = gearToothSDF(gearMap, vec3(0.04, 0.06, 0.02), .005, brick);
    MapReturn squareRing = squareRingSDF(gearPosition, 0.155, 0.06, 0.036, brick);
    MapReturn crossed = crossSDF(position - vec3(0., .47, 0.), vec3(.16, .005, .005), rustyMetal);
    MapReturn crossedRound = opRound(crossed, .003);
    MapReturn vStick = vStickSDF(position, .47, .01, rustyMetal);

    MapReturn u1 = opUnion(roundedBox, squareRing);
    MapReturn u2 = opUnion(crossedRound, u1);
    MapReturn u3 = opUnion(vStick, u2);

    u3.texturePosition = position;

    return u3;
}

MapReturn oldMap(vec3 position) {
	position.yz *= rot(.07*position.x);
    position.z += sin(position.x)*.1;
    position.y += sin(position.x+1.)*.04;

    //position.z += sin(position.x*3.)*.1;

    float scale = sin(position.x/4.+6.)/3. + 1.;
    scale = 1.;

    MapReturn floorD = planeSDF(position, vec3(0., 1., 0.), -1.*scale, brick);
    MapReturn ceilingD = planeSDF(position, vec3(0., 1., 0.), 1.*scale, brick);
    MapReturn floorsD = opUnion(floorD, ceilingD);
    MapReturn leftWallD = planeSDF(position, vec3(0., 0., 1.), -1.*scale, brick);
    MapReturn rightWallD = planeSDF(position, vec3(0., 0., 1.), 1.*scale, brick);
    MapReturn wallsD = opUnion(leftWallD, rightWallD);

    position.x -= iTime*SPEED+4.;

    MapReturn sphereD = sphereSDF(position, .3, brass);

    return opUnion(opUnion(floorsD, wallsD), sphereD);
    //return opUnion(floorsD, wallsD);
}

MapReturn alsoOldMap(vec3 position) {
	float scaling = 1.;

	for (int i = 0; i < 8; i++) {
		position = 2. * fract(.5 * position + .5) - 1.;

		float r2 = dot(position, position);
		float scalingFactor = (1.1 + 0.5 * smoothstep(-0.3, 0.3, cos(0.1 * iTime))) / r2;
		position *= scalingFactor;
		scaling *= scalingFactor;
	}

	MapReturn mp;
	mp.sdf = .25 * abs(position.y) / scaling;
	mp.material = white;
	return mp;
}

MapReturn map(vec3 position) {

    vec3 q = position;
    if (abs(q.x) > abs(q.y) && abs(q.x) > abs(q.z)) q = q.yxz;
    else if(abs(q.z) > abs(q.y)) q = q.xzy;
    else q = q.xyz*vec3(-1., 1., 1.);

    MapReturn gear1 = gearSDF(q, iTime, 0.);

    vec3 qx = vec3(rot(PI/4.) * position.zy*-1., position.x);
    if (abs(qx.x)>abs(qx.y)) qx = qx.zxy;
    MapReturn gear2 = gearSDF(qx, -iTime, 1.);

    vec3 qy = vec3(rot(PI/4.) * position.xz*-1., position.y);
    if (abs(qy.x)>abs(qy.y)) qy = qy.zxy;
    MapReturn gear3 = gearSDF(qy, -iTime, 1.);

    vec3 qz = vec3(rot(PI/4.) * position.xy*-1., position.z);
    if (abs(qz.x)>abs(qz.y)) qz = qz.zxy;
    MapReturn gear4 = gearSDF(qz, iTime, 1.);

    MapReturn centerSphere = sphereSDF(position, .1, brick);

    MapReturn u1 = opUnion(gear1, gear2);
    MapReturn u2 = opUnion(u1, gear3);
    MapReturn u3 = opUnion(u2, gear4);
    MapReturn u4 = opUnion(u3, centerSphere);

    return u4;
}

MapReturn rayMarch(vec3 rayOrigin, vec3 rayDirection) {
    float surfaceDistance, distanceTravelled = 0.;
    Material material = missing;
    vec3 texturePosition = vec3(0.);

    for (int i = 0; i < MAX_STEPS; i++) {
        MapReturn sdfResult = map(rayOrigin + rayDirection * distanceTravelled);
        surfaceDistance = sdfResult.sdf;


        if (surfaceDistance < sEPS) {
            material = sdfResult.material;
            texturePosition = sdfResult.texturePosition;
            break;
        }

        if (distanceTravelled > FAR) break;

        distanceTravelled += surfaceDistance;
    }

    MapReturn mp;
    mp.sdf = distanceTravelled;
    mp.material = material;
    mp.texturePosition = texturePosition;
    return mp;
}

VolumetricReturn volumetricSphereSDF(vec3 position, float radius, vec3 color) {
	VolumetricReturn vr;
	vr.color = color;

	vr.density = -(length(position) - radius);

	return vr;
}

VolumetricReturn volumetricBoxSDF(vec3 position, vec3 bounds, vec3 color) {
	VolumetricReturn vr;
	vr.color = color;

    vec3 q = abs(position) - bounds;
    vr.density = -length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);

    return vr;
}

VolumetricReturn volumetricMap(vec3 position) {	
	VolumetricReturn sphereD = volumetricSphereSDF(position, 1., vec3(1.));
	float f = fbm_6(position+iTime)*.5;
	sphereD.density += f;
	return sphereD;
}

vec4 volumetricRayMarch(vec3 rayOrigin, vec3 rayDirection, float opaqueDepth) {
	vec3 currentPosition = rayOrigin;

	vec4 res = vec4(0.);

	for (int i = 0; i < MAX_STEPS; i++) {
		float currentDepth = length(currentPosition - rayOrigin);

		if (currentDepth >= opaqueDepth) break;

		VolumetricReturn volume = volumetricMap(currentPosition);

		if (volume.density > 0.) {
			vec3 sunDirection = normalize(vec3(-10., 10., 10.) - currentPosition);
			float diffuse = clamp(volumetricMap(currentPosition).density-volumetricMap(currentPosition + 0.3 * sunDirection).density/ 0.3, 0., 1.); 

			vec3 lin = vec3(0.60,0.60,0.75) * 1.1 + 0.8 * vec3(1.0,0.6,0.3) * diffuse;

			vec4 color = vec4(mix(vec3(1.), vec3(0.), volume.density), volume.density);

			color.rgb *= lin;
			color.rgb *= color.a;
			res += color * (1. - res.a);
		}

		currentPosition += rayDirection * VOLUMETRIC_STEP_SIZE;

		if (currentDepth >= FAR) break;
	}

	return res;
}

vec3 getNormal(in vec3 p) {
	const float eps = 0.001;
	return normalize(vec3(
		map(vec3(p.x+eps,p.y,p.z)).sdf-map(vec3(p.x-eps,p.y,p.z)).sdf,
		map(vec3(p.x,p.y+eps,p.z)).sdf-map(vec3(p.x,p.y-eps,p.z)).sdf,
		map(vec3(p.x,p.y,p.z+eps)).sdf-map(vec3(p.x,p.y,p.z-eps)).sdf
	));
}

// Tri-Planar blending function. Based on an old Nvidia writeup:
// GPU Gems 3 - Ryan Geiss: http://http.developer.nvidia.com/GPUGems3/gpugems3_ch01.html
vec3 tex3D( sampler2D tex, in vec3 p, in vec3 n ){

    //n = abs(n)/1.732051;
    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z );  

	return (texture(tex, p.yz)*n.x + texture(tex, p.zx)*n.y + texture(tex, p.xy)*n.z).xyz;
}

float softShadow(vec3 rayOrigin, vec3 rayDirection, float minDist, float maxDist, float w) {
    float shade = 1.;
    const int maxIterations = 32;

    float dist = minDist;
    float stepDist = maxDist/float(maxIterations);

    for (int i = 0; i < maxIterations; i++) {
        float h = map(rayOrigin + rayDirection*dist).sdf;
        shade = min(shade, w*h/dist);

        dist += clamp(h, 0.0005, stepDist*2.);

        if (h < 0.001 || dist > maxDist) break;
    }

    return min(max(shade, 0.) + 0.4, 1.);
}

float calculateAmbientOcclusion(vec3 rayOrigin, vec3 surfaceNormal) {
    const float AO_SAMPLES = 5.;
    float occ = 0.;
    float sca = 0.5;
    float dist;

    for (float i = 1.; i < AO_SAMPLES+1.1; i++) {
        dist = i/AO_SAMPLES;
        occ += sca*(dist - map(rayOrigin + surfaceNormal * dist).sdf);
        sca *= 0.5;
    }

    return 1. - clamp(occ, 0., 1.);
}

vec3 render(vec3 rayOrigin, vec3 rayDirection) {
    vec3 lightPosition = rayOrigin;

    // Scene color is initialized to black
    vec3 sceneColor = (vec3(.529,.808,.922)+rayDirection.y)*0.2;

    #ifdef ENABLE_OPAQUE
    MapReturn raymarchResult = rayMarch(rayOrigin, rayDirection);
    vec4 volumetricContribution = volumetricRayMarch(rayOrigin, rayDirection, raymarchResult.sdf);
    float surfaceDistance = raymarchResult.sdf;
    Material objectMaterial = raymarchResult.material;
    #else
    vec4 volumetricContribution = volumetricRayMarch(rayOrigin, rayDirection, FAR);
    #endif

    #ifdef ENABLE_OPAQUE
    if (surfaceDistance < FAR) {

        vec3 surfacePoint = rayOrigin + rayDirection * surfaceDistance;

        vec3 surfaceNormal = getNormal(surfacePoint);

        // TODO - bump map here updates surfaceNormal

        #ifdef NORMALS_DEBUG
        vec3 objectColor = .5 + .5 * surfaceNormal;
        #else
        vec3 objectColor;

        /*
        if (objectMaterial.textureID == -1) {
        	objectColor = objectMaterial.color;
        } else if (objectMaterial.textureID == 1) {
        	objectColor = tex3D(iChannel1, surfacePoint, surfaceNormal);
        } else if (objectMaterial.textureID == 2) {
        	objectColor = tex3D(iChannel2, surfacePoint, surfaceNormal);
        }*/

        if (objectMaterial.textureID == -1) {
        	objectColor = objectMaterial.color;
        } else if (objectMaterial.textureID == 1) {
        	objectColor = 0.5*texture(iChannel1, raymarchResult.texturePosition.xy).xyz +
                           0.5*texture(iChannel1, raymarchResult.texturePosition.xz).xyz;
        } else if (objectMaterial.textureID == 2) {
        	objectColor = 0.5*texture(iChannel2, raymarchResult.texturePosition.xy).xyz +
                           0.5*texture(iChannel2, raymarchResult.texturePosition.xz).xyz;
        }

        #endif

        vec3 lightDirection = lightPosition-surfacePoint;
        float lightDistance = max(length(lightDirection), .001); // Distance from light to surface point
        lightDirection /= lightDistance; // Normalize

        #ifdef ATTENUATION
        float attenuation = min(1.0 / (lightDistance*0.3 + lightDistance*lightDistance*0.05), 1.);
        #else
        float attenuation = 1.;
        #endif

        // Phong Lighting Approach
        // TODO - Investigate BRDF
        PhongParameters phong = objectMaterial.phongParameters;

        float phongDiffuse = max(0.0, dot(surfaceNormal, lightDirection));
        float phongSpecular = max(0.0, dot(reflect(-lightDirection, surfaceNormal), -rayDirection));
        phongSpecular = pow(phongSpecular, phong.specularExponent);

        // IQ Soft Shadows
        #ifdef SHADOWS
        float shadow = softShadow(surfacePoint, lightDirection, sEPS*2., lightDistance, 32.);
        #else
        float shadow = 1.;
        #endif

        // Ambient occlusion
        #ifdef AMBIENT_OCCLUSION
        float ambientOcclusion = calculateAmbientOcclusion(surfacePoint, surfaceNormal);
        #else
        float ambientOcclusion = 1.;
        #endif

        #ifdef PHONG_SHADING
        sceneColor = objectColor*(phongDiffuse*phong.diffuse + phong.ambient) 
                   + phongSpecular*phong.specular*0.75;
        #else
        sceneColor = objectColor;
        #endif

        sceneColor *= attenuation*shadow*ambientOcclusion;
    }
    #endif

    #ifdef ENABLE_VOLUMETRIC
    vec3 finalColor = mix(sceneColor, volumetricContribution.rgb, volumetricContribution.a);
    #else
    vec3 finalColor = sceneColor; 
    #endif

    return finalColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    setMaterials();

    vec3 total = vec3(0);

    for (int i = 0; i < AA; i++) {
        for (int j = 0; j < AA; j++) {
            vec2 updatedFragCoord = (fragCoord + vec2(float(i),float(j))/float(AA)-0.5);
            vec2 uv = (updatedFragCoord - iResolution.xy*0.5) / iResolution.y;

            vec3 rayOrigin = vec3(1., .7, 0.);
            //rayOrigin.xy = rot(sin(iTime*1.5)*.5) * rayOrigin.xy;
            rayOrigin.xz = rot(iTime*.15) * rayOrigin.xz;


            vec3 lookAt = vec3(0., 0., 0.);

            float FOV = 1.25;
            vec3 forward = normalize(lookAt - rayOrigin);
            vec3 right = normalize(vec3(forward.z, 0., -forward.x));
            vec3 up = cross(forward, right);

            vec3 rayDirection = normalize(uv.x*right + uv.y*up + forward/FOV);

            //rayDirection.xz *= rot(iTime*0.7);


            total += render(rayOrigin, rayDirection);
        }
    }

    total /= float(AA*AA);

    fragColor = vec4(clamp(total, 0., 1.), 1.0);
}
